<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAsset;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetWriteGateway;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetAttributes;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetCreateUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateAssetVisibilityService $visibility,
    private readonly TemplateAssetWriteGateway $writer,  ) {
  }

  public function allowCreate(): Allow
  {
    $this->logDebug("Check allow of create usecase for Template asset");
    $span = $this->startSpan("Check allow of create usecase for Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function create(TemplateAssetCreateParams $params): TemplateAssetCreateResult
  {
    $this->logDebug("Run create usecase for Template asset");
    $span = $this->startSpan("Run create usecase for Template asset");
    try {
      $allow = $this->allowCreate();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Template asset');
      }
      $this->dispatcher->dispatch( new TemplateAssetCreateCheck($params) );      $enriched = $this->dispatcher->dispatch( new TemplateAssetCreateEnrich( $params, $params->toAttributes() ) );      $attributes = $enriched->getResult();
      $input = $this->visibility->copyWithFixed( $attributes );
      $entity = TemplateAsset::create( $input );
      $result = $this->writer->create($entity, fn(TemplateAsset $created) =>
                      $this->visibility->checkVisibility($created)
      );
      $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData( $result ));
      return new TemplateAssetCreateResult( $output );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
